function diagonalGroups(matrix) {
  const rows = matrix.length, cols = matrix[0].length;
  const diagonals = Array.from({ length: rows + cols - 1 }, () => []);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      diagonals[r + c].push(matrix[r][c]);    // same r + c, same diagonal
    }
  }
  return diagonals;
}

def diagonal_groups(matrix):
    rows, cols = len(matrix), len(matrix[0])
    diagonals = [[] for _ in range(rows + cols - 1)]
    for r in range(rows):
        for c in range(cols):
            diagonals[r + c].append(matrix[r][c])   # same r + c, same diagonal
    return diagonals

class Solution {
    public List<List<Integer>> diagonalGroups(int[][] matrix) {
        int rows = matrix.length, cols = matrix[0].length;
        List<List<Integer>> diagonals = new ArrayList<>();
        for (int d = 0; d < rows + cols - 1; d++) diagonals.add(new ArrayList<>());
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                diagonals.get(r + c).add(matrix[r][c]);   // same r + c, same diagonal
            }
        }
        return diagonals;
    }
}

class Solution {
public:
    vector<vector<int>> diagonalGroups(vector<vector<int>>& matrix) {
        int rows = matrix.size(), cols = matrix[0].size();
        vector<vector<int>> diagonals(rows + cols - 1);
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                diagonals[r + c].push_back(matrix[r][c]);   // same r + c, same diagonal
            }
        }
        return diagonals;
    }
};
